<script>import {router} from './router.js';import {authStore} from './features/auth/states/authStore.js';import AuthLayout from './features/auth/layouts/AuthLayout.svelte';import LoginPage from './features/auth/pages/LoginPage.svelte';import RegisterPage from './features/auth/pages/RegisterPage.svelte';import LinkTreeLayout from './features/linktrees/layouts/LinkTreeLayout.svelte';import HomePage from './features/linktrees/pages/HomePage.svelte';import DetailPage from './features/linktrees/pages/DetailPage.svelte';import UsersPage from './features/users/pages/UsersPage.svelte';import ProfilePage from './features/users/pages/ProfilePage.svelte';import NotFoundPage from './features/auth/pages/NotFoundPage.svelte';let path=$derived(router.path);let isAuth=$derived(path==='/auth/login'||path==='/auth/register');let valid=$derived(path==='/'||path==='/users'||path==='/profile'||/^\/link-trees\/[^/]+$/.test(path));$effect(()=>{if(!isAuth&&!authStore.isAuthenticated){router.replace('/auth/login')}else if(isAuth&&authStore.isAuthenticated){router.replace('/')}});</script>
{#if isAuth}<AuthLayout>{#if path==='/auth/register'}<RegisterPage/>{:else}<LoginPage/>{/if}</AuthLayout>{:else if !authStore.isAuthenticated}<AuthLayout><LoginPage/></AuthLayout>{:else if valid}<LinkTreeLayout>{#if path==='/'}<HomePage/>{:else if path==='/users'}<UsersPage/>{:else if path==='/profile'}<ProfilePage/>{:else}<DetailPage/>{/if}</LinkTreeLayout>{:else}<NotFoundPage/>{/if}
